<script lang="ts">import { onMount } from "svelte"; let file = null; let width = 256; let height = 256; let pngUrl = null; async function openFile() { const [path] = await (window as any).__TAURI__.dialog.open({ multiple: false }); if (!path) return; file = await (window as any).__TAURI__.invoke("open_xvg", { path }); } async function saveAs() { if (!file) return; const path = await (window as any).__TAURI__.dialog.save(); if (!path) return; await (window as any).__TAURI__.invoke("save_xvg", { file, path }); }</script><main class="p-8 bg-slate-100 min-h-screen font-sans"><h1 class="text-3xl font-bold text-slate-800 mb-6">XVG Tesseract Viewer</h1><section class="mb-6"><button on:click={openFile} class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Open .xvg</button><button on:click={saveAs} disabled={!file} class="ml-2 bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 disabled:opacity-50">Save .xvg</button></section>{#if file}<section class="mb-6"><h2 class="text-xl font-semibold mb-2">Header</h2><pre class="text-sm bg-slate-200 p-2 rounded">{JSON.stringify(file.header, null, 2)}</pre></section>{/if}</main>
